-- ── SELF-CHECK (CLAUDE.md §4): the rows the generator wrote, and nothing more ──
do $$
declare v_role text; v_t text;
begin
  if (select count(*) from public.hr_hunt_supplies) <> 59
     or (select count(*) from public.hr_hunt_travel) <> 115
     or (select count(*) from public.hr_hunt_limits) <> 52
     or (select count(*) from public.hr_hunt_end_reasons) <> 11
     or (select count(*) from public.hr_hunt_vendor_value) <> 480
     or (select count(*) from public.hr_hunt_basic_supplies) <> 18
     or (select count(*) from public.hr_hunt_cover_items) <> 0
     or (select count(*) from public.hr_hunt_travel where tier is null) <> 0
     or (select count(*) from public.hr_hunt_target_modes) <> 5
     or (select count(*) from public.hr_hunt_resumable_kinds) <> 3
     or (select count(*) from public.hr_hunt_lanes) <> 3
     or (select count(*) from public.hr_hunt_set_options) <> 13
     or (select count(*) from public.hr_hunt_kill_bounds) <> 129
     or (select count(*) from public.hr_hunt_abilities) <> 14
     or (select count(*) from public.hr_hunt_grounds) <> 4
     or (select count(*) from public.hr_hunt_ground_spawns) <> 19
     or (select count(*) from public.hr_hunt_world_shape) <> 1
     or (select count(*) from public.hr_premium_login_reward) <> 1
     or (select count(*) from public.hr_hunt_weapons) <> 62
     or (select count(*) from public.hr_hunt_weapon_roles) <> 12
     or (select count(*) from public.hr_hunt_roles) <> 5
     or (select count(*) from public.hr_hunt_end_reasons where resumes) <> 9 then
    raise exception 'hunt-session catalogue row counts moved from the generator''s'; end if;
  -- The world fields the party section reads by name are all there, at the generator's positions.
  if (select fields from public.hr_hunt_world_shape) is distinct from '{"unit":{"id":0,"side":1,"kind":2,"pocket":3,"alive":4,"hp":5,"maxHp":6,"target":7,"home":8,"x":9,"y":10,"fx":11,"fy":12,"prog":13,"speed":14,"dir":15,"goal":16,"path":17,"waitMs":18,"repathMs":19,"spot":20,"chalMs":21,"role":22,"dist":23,"chase":24,"tmode":25,"queued":26,"aiMs":27,"deadMs":28,"hpMilli":29,"yieldPm":30,"stance":31,"acc":32,"maxHit":33,"def":34,"element":35,"swingLeftMs":36,"mana":37,"maxMana":38,"manaMilli":39,"regenPm":40,"lanes":41,"cds":42,"shield":43,"markBy":44,"markUntil":45,"vulnUntil":46,"statuses":47,"laneAt":48,"otHp":49,"otMana":50,"healedAt":51,"ruleHold":52,"ruleWait":53},"world":{"ground":0,"swing":1,"leader":2,"trail":3,"leaderLast":4,"phase":5,"routeIdx":6,"phaseMs":7,"regroupNext":8,"runs":9,"nextId":10,"density":11,"xpGroup":12}}'::jsonb
     or exists (select 1 from unnest(array['id', 'side', 'kind', 'alive', 'x', 'y', 'hp', 'maxHp', 'target', 'mana', 'maxMana', 'shield', 'otHp', 'otMana', 'role', 'dist', 'chase', 'tmode', 'stance']) n
                 where not ((select fields->'unit' from public.hr_hunt_world_shape) ? n)) then
    raise exception 'hr_hunt_world_shape.fields is not world-state.js FIELDS'; end if;
  -- ONE consumable lane, at the data file's ms (the food-lane ruling, spec §3.4 #3).
  if (select ms from public.hr_hunt_lanes where lane = 'consumable') is distinct from 2000 then
    raise exception 'the consumable lane is not consumables.js laneMs'; end if;
  -- Premium may never rest less than free; the core model's curves are live (a Level and a skill both start at 0 XP).
  if public.hr_hunt_limit('stamina_premium_min') < public.hr_hunt_limit('stamina_free_min')
     or coalesce(public.hr_hunt_limit('level_cubic'), 0) <= 0 or coalesce(public.hr_hunt_limit('skill_base'), 0) <= 0
     or coalesce(public.hr_hunt_limit('armour_slots'), 0) <= 0 then
    raise exception 'the stamina caps or the core model rows are malformed'; end if;
  -- Every supply, vendor value, ability rune and login reward is a catalogued item;
  -- every named hunt and ground hunt is in hr_hunts; every training id is a
  -- non-boss combat target; every ground spawn has a kill bound.
  if exists (select 1 from public.hr_hunt_supplies s where not exists (select 1 from public.hr_items i where i.item_id = s.item_id))
     or exists (select 1 from public.hr_hunt_vendor_value v where not exists (select 1 from public.hr_items i where i.item_id = v.item_id))
     or exists (select 1 from public.hr_hunt_abilities a where a.active and a.rune is not null
                  and not exists (select 1 from public.hr_items i where i.item_id = a.rune))
     or exists (select 1 from public.hr_premium_login_reward l where l.item_id is not null
                  and not exists (select 1 from public.hr_items i where i.item_id = l.item_id)) then
    raise exception 'a supply, vendor-value, ability-rune or login-reward row names an item hr_items does not have'; end if;
  if exists (select 1 from public.hr_hunt_travel t where not t.training
               and not exists (select 1 from public.hr_hunts h where h.hunt_id = t.hunt_id))
     or exists (select 1 from public.hr_hunt_grounds g where not exists (select 1 from public.hr_hunts h where h.hunt_id = g.hunt_id)) then
    raise exception 'a named hunt or a ground hunt is not in hr_hunts'; end if;
  if exists (select 1 from public.hr_hunt_travel t where t.training
               and not exists (select 1 from public.hr_activities a
                                where a.kind = 'combat' and a.activity_id = t.hunt_id and not a.is_boss)) then
    raise exception 'a training id in hr_hunt_travel is not a non-boss combat target'; end if;
  if exists (select 1 from public.hr_hunt_ground_spawns s
               where not exists (select 1 from public.hr_hunt_kill_bounds b where b.monster_id = s.monster_id)) then
    raise exception 'a ground spawns a monster with no kill bound'; end if;
  -- The Magic-XP bound covers the biggest store drink at one drink a consumable lane (else a settle that
  -- drank the basics it bought is refused as over-bound).
  if public.hr_hunt_limit('drink_mana_per_min_max')
       < (60000 / (select ms from public.hr_hunt_lanes where lane = 'consumable'))
         * (select coalesce(max(mana), 0) from public.hr_hunt_basic_supplies where kind = 'mana') then
    raise exception 'drink_mana_per_min_max is under the store drinks at one per consumable lane'; end if;
  -- No client role reads or writes any of them; no policy exists.
  foreach v_role in array array['anon', 'authenticated'] loop
    foreach v_t in array array['hr_hunt_supplies', 'hr_hunt_travel', 'hr_hunt_limits', 'hr_hunt_end_reasons', 'hr_hunt_vendor_value', 'hr_hunt_target_modes', 'hr_hunt_resumable_kinds', 'hr_hunt_basic_supplies', 'hr_hunt_cover_items', 'hr_hunt_lanes', 'hr_hunt_set_options', 'hr_hunt_kill_bounds', 'hr_hunt_abilities', 'hr_hunt_grounds', 'hr_hunt_ground_spawns', 'hr_hunt_world_shape', 'hr_premium_login_reward', 'hr_hunt_weapons', 'hr_hunt_weapon_roles', 'hr_hunt_roles'] loop
      if has_table_privilege(v_role, 'public.' || v_t, 'select,insert,update,delete,truncate') then
        raise exception '% holds a privilege on %', v_role, v_t; end if;
    end loop;
  end loop;
  if exists (select 1 from pg_policies where schemaname = 'public' and tablename in ('hr_hunt_supplies', 'hr_hunt_travel', 'hr_hunt_limits', 'hr_hunt_end_reasons', 'hr_hunt_vendor_value', 'hr_hunt_target_modes', 'hr_hunt_resumable_kinds', 'hr_hunt_basic_supplies', 'hr_hunt_cover_items', 'hr_hunt_lanes', 'hr_hunt_set_options', 'hr_hunt_kill_bounds', 'hr_hunt_abilities', 'hr_hunt_grounds', 'hr_hunt_ground_spawns', 'hr_hunt_world_shape', 'hr_premium_login_reward', 'hr_hunt_weapons', 'hr_hunt_weapon_roles', 'hr_hunt_roles')) then
    raise exception 'a policy exists on the hunt-session catalogue'; end if;
end $$;
